//! Windows 98's and 2000's own 16-color drawings of the pictures Bevel95 draws in their looks
//! (generated by `private/probes/colors16/match`, which finds each True Color picture among the
//! Reference PCs' own files: the 8-bit twin of a 4-bit icon in SHELL32, EXPLORER and MYDOCS, and
//! the toolbars' strips, 98's cut from its screens and 2000's from BROWSEUI.DLL; the report of what
//! matched is beside it). A picture listed here is shown with its own drawing in 16 colors
//! (`colors16::picture`); any other is converted by its Windows' rule. Each drawing is used only in
//! the look it came from. The grayed toolbar pictures are made from the plain ones' drawings the
//! way Windows grays a picture (a white copy under a gray one). Rows: '.' see-through, else the
//! color's number among the 16 (`colors16::VGA`) in hexadecimal. The drawings themselves are
//! Windows' and kept in bevel-art (`art/src/colors16.rs`, written by the same program).

use std::collections::HashMap;
use std::sync::OnceLock;

use crate::art::Look;
use crate::fb::Icon;
use crate::theme::Era;

/// A look, the function that draws one of its True Color pictures, and its 16-color drawing.
type Own = (Era, fn() -> Option<Icon>, &'static Drawing);

/// A 16-color drawing.
pub(crate) struct Drawing {
    w: i32,
    h: i32,
    rows: &'static [&'static str],
}

impl Drawing {
    /// The drawing `what` of `look` (Windows' own, in 16 colors), from bevel-art.
    const fn art(what: &str, look: Look) -> Drawing {
        let r = crate::art::rows_at(what, look, bevel_art::Depth::Sixteen);
        Drawing { w: r.w, h: r.h, rows: r.rows }
    }

    fn icon(&self) -> Icon {
        let pixels = self
            .rows
            .iter()
            .flat_map(|r| r.chars())
            .map(|c| c.to_digit(16).map_or(0, |i| crate::colors16::vga(i as usize)))
            .collect();
        Icon { width: self.w, height: self.h, pixels }
    }
}

/// A picture's fingerprint: its size and every pixel.
fn key(icon: &Icon) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for v in [icon.width as u32, icon.height as u32].iter().chain(&icon.pixels) {
        for b in v.to_le_bytes() {
            h = (h ^ u64::from(b)).wrapping_mul(0x0100_0000_01b3);
        }
    }
    h
}

/// `era`'s own 16-color drawing of `icon` (a True Color picture Bevel95 draws), if it had one.
pub(crate) fn own(era: Era, icon: &Icon) -> Option<Icon> {
    static MAP: OnceLock<HashMap<(u8, u64), Icon>> = OnceLock::new();
    let map = MAP.get_or_init(|| {
        let mut map = HashMap::new();
        for (era, source, drawing) in OWN {
            if let Some(picture) = source() {
                map.entry((*era as u8, key(&picture))).or_insert_with(|| drawing.icon());
            }
        }
        map
    });
    map.get(&(era as u8, key(icon))).cloned()
}

